private static void buildAOE() {
    for (int i = 0; i < 8; i++) {
        aoe.add(new VertexNode(i));
    }
    BufferedReader br = null;
    try {
        br = new BufferedReader(new FileReader("data.txt"));
        String line = null;
        while ((line = br.readLine()) != null) {
            VertexNode node = aoe.get(Integer.parseInt(line.split(" ")[0]));
            EdgeNode edge = node.getFirstEdge();
            if (edge == null) {
                node.setFirstEdge(new EdgeNode(Integer.parseInt(line.split(" ")[3]),
                        line.split(" ")[1], Integer.parseInt(line.split(" ")[2]),
                        Integer.parseInt(line.split(" ")[0])));
            } else {
                while (edge.getNextNode() != null) {
                    edge = edge.getNextNode();
                }
                edge.setNextNode(new EdgeNode(Integer.parseInt(line.split(" ")[3]),
                        line.split(" ")[1], Integer.parseInt(line.split(" ")[2]),
                        Integer.parseInt(line.split(" ")[0])));
            }
        }
        System.out.println("AOE网建立完成。");
    } catch (Exception e) {
        System.out.println("建立AOE网时有错误发生。");
        System.exit(1);
    } finally {
        if (br != null) {
            try {
                br.close();
            } catch (IOException e) {
                System.out.println("关闭流时有错误发生。");
            }
        }
    }
}

private static void showAOE() {
