        System.out.print(node.getVertex() + " ==> ");
        while (edge.getNextNode() != null) {
            System.out.print(edge.getEvent() + "," + edge.getTime() + "," + edge.getVertex() + " --> ");
            edge = edge.getNextNode();
        }
        System.out.println(edge.getEvent() + "," + edge.getTime() + "," + edge.getVertex());
    }
}

private static void findKeyWay() {
    VertexNode startNode = aoe.get(0);
    VertexNode lastNode = aoe.get(7);
    DFS(startNode, lastNode);
    int[] times = new int[results.size()];
    for (int i = 0; i < results.size(); i++) {
        times[i] = 0;
    }
    for (int i = 0; i < results.size(); i++) {
        ArrayList<VertexNode> path = results.get(i);
        for (int j = 0; j < path.size() - 1; j++) {
            int target = path.get(j + 1).getVertex();
            VertexNode node = path.get(j);
            EdgeNode edge = node.getFirstEdge();
            while (edge != null) {
                if (edge.getVertex() == target) {
                    times[i] += edge.getTime();
                    break;
                }
                edge = edge.getNextNode();
            }
        }
    }
    int maxIndex = 0;
    for (int i = 0; i < times.length; i++) {
        if (times[i] > times[maxIndex]) {
            maxIndex = i;
        }
    }
    keyWay = results.get(maxIndex);
    System.out.println("该工程至少需要" + times[maxIndex] + "天完成");
    System.out.println("关键工程顺序如下：");
    for (int j = 0; j < keyWay.size() - 1; j++) {
