}

private static void DFS(VertexNode startNode, VertexNode lastNode) {
    stack.push(startNode);
    visit[startNode.getVertex()] = true;
    while (!stack.isEmpty()) {
        VertexNode top = stack.getTop();
        if (top.getVertex() == lastNode.getVertex()) {
            results.add(stack.getList());
            stack.pop();
            visit[lastNode.getVertex()] = false;
            break;
        } else {
            EdgeNode edge = startNode.getFirstEdge();
            while (edge != null) {
                if (!visit[edge.getVertex()]) {
                    DFS(aoe.get(edge.getVertex()), lastNode);
                }
                edge = edge.getNextNode();
            }
            if (edge == null) {
                stack.pop();
                visit[startNode.getVertex()] = false;
                break;
            }
        }
    }
}

